__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int N) {
    // Double buffered shared memory
    __shared__ float As[2][TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[2][TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    // Preload first tile
    int a_col = threadIdx.x;
    int b_row = threadIdx.y;

    if (row < N && a_col < N) {
        As[0][threadIdx.y][threadIdx.x] = A[row * N + a_col];
    } else {
        As[0][threadIdx.y][threadIdx.x] = 0.0f;
    }

    if (b_row < N && col < N) {
        Bs[0][threadIdx.y][threadIdx.x] = B[b_row * N + col];
    } else {
        Bs[0][threadIdx.y][threadIdx.x] = 0.0f;
    }

    __syncthreads();

    int current = 0;
    int next = 1;

    // Loop over tiles
    for (int tile = 1; tile <= (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Preload next tile while computing current tile
        if (tile < (N + TILE_SIZE - 1) / TILE_SIZE) {
            a_col = tile * TILE_SIZE + threadIdx.x;
            b_row = tile * TILE_SIZE + threadIdx.y;

            if (row < N && a_col < N) {
